  onArchiveSkeleton: (skeletonId: string) => void;
  onTestLogic: (template: Template) => void;
  onArchive: (templateId: string) => void;
  onUpdateSite: (templateId: string, siteId: string) => void;
  onOpenSiteDetails: (template?: Template) => void;
  onCreateDraft?: (template: Template) => void;
}

const getStatusStyles = (status: string) => {
  switch (status) {
    case 'Published':
      return 'text-emerald-700 bg-emerald-50 border-emerald-200 font-bold';
    case 'Rolling Out':
      return 'text-purple-700 bg-purple-50 border-purple-200 font-bold';
    case 'Draft':
      return 'text-amber-700 bg-amber-50 border-amber-200 font-bold';
    case 'Archived':
      return 'text-gray-700 bg-gray-50 border-gray-200';
    case 'Snapshot':
      return 'text-slate-600 bg-slate-100 border-slate-200';
    default:
      return 'text-gray-700 bg-gray-50 border-gray-200';
  }
};

interface VersionRowProps {
  version: string;
  status: string;
  lastUpdated: string;
  updatedBy: string;
  isCurrent: boolean;
  onView: () => void;
}

const VersionRow: React.FC<VersionRowProps> = ({ 
  version, 
  status, 
  lastUpdated, 
  updatedBy, 
  isCurrent, 
  onView
}) => {
  const isDraft = status === 'Draft';

  return (
    <tr className={`group transition-colors hover:bg-gray-50/50 ${isCurrent ? 'bg-indigo-50/10' : ''}`}>
      <td className="px-6 py-4 whitespace-nowrap">
        <button 
          onClick={(e) => { e.stopPropagation(); onView(); }}
          className="flex items-center gap-2 group/ver outline-none text-left"
        >
           <span className={`font-mono text-sm transition-all ${
             isCurrent 
               ? 'font-bold text-indigo-700' 
               : 'font-semibold text-gray-900 group-hover/ver:text-indigo-600 group-hover/ver:underline'
           }`}>
             v{version}
           </span>
        </button>
      </td>

      <td className="px-6 py-4 whitespace-nowrap">
        <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[10px] uppercase tracking-wider border ${getStatusStyles(status)}`}>
          {status}
        </span>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
          <div className="flex items-center gap-1.5">
             <Clock className="w-3.5 h-3.5 text-gray-400" />
             {lastUpdated}
          </div>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
          <div className="flex items-center gap-1.5">
             <User className="w-3.5 h-3.5 text-gray-400" />
             {updatedBy}
          </div>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-right">
        <div className="flex items-center justify-end gap-2">
            <button
            onClick={(e) => { e.stopPropagation(); onView(); }}
            className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg border text-xs font-medium transition-colors shadow-sm ${
                isDraft
                ? 'border-indigo-200 bg-indigo-50 text-indigo-700 hover:bg-indigo-100'
                : 'border-gray-200 bg-white text-gray-700 hover:bg-gray-50 hover:text-indigo-600'
            }`}
            >
            {isDraft ? <PenLine className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
            {isDraft ? 'Edit' : 'View'}
            </button>
        </div>
      </td>
    </tr>
  );
};

export const TemplateList: React.FC<TemplateListProps> = ({ templates, sitesByTemplate, onSelectVersion, onCreateTemplate, onOpenSiteDetails, onTestLogic, onCreateDraft }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const activeTemplate = templates.length > 0 ? templates[0] : null;

  const versions = useMemo(() => {
      if (!activeTemplate) return [];

      const list = [
          {
              version: activeTemplate.version,
              status: activeTemplate.status,
              lastUpdated: activeTemplate.lastUpdated,
              updatedBy: activeTemplate.updatedBy || 'Unknown',
              isCurrent: true
          }
      ];

      if (activeTemplate.history && activeTemplate.history.length > 0) {
          activeTemplate.history.forEach(h => {
              const verNum = parseFloat(h.version);

              let inferredStatus: string;
              // If main is Draft, then previous version is Rolling Out (for mock purposes)
              if (activeTemplate.status === 'Draft' && h.version === activeTemplate.previousVersion) {
                  inferredStatus = 'Rolling Out';
              } else {
                  const isArchivedMinor = !isNaN(verNum) && verNum < parseFloat(activeTemplate.version);
                  const isMajor = h.version.endsWith('.0');
                  inferredStatus = isMajor ? 'Published' : 'Archived';

                  // If it's old history, mark as Archived
                  if (!isMajor || (activeTemplate.previousVersion && parseFloat(h.version) < parseFloat(activeTemplate.previousVersion))) {
                      inferredStatus = 'Archived';
                  }
              }

              list.push({
                  version: h.version,
                  status: inferredStatus,
                  lastUpdated: h.lastUpdated,
                  updatedBy: h.updatedBy,
                  isCurrent: false
              });
          });
      }

      if (searchQuery) {
          return list.filter(v => v.version.includes(searchQuery) || v.updatedBy.toLowerCase().includes(searchQuery.toLowerCase()));
      }

      return list.sort((a, b) => parseFloat(b.version) - parseFloat(a.version));
  }, [activeTemplate, searchQuery]);

  const totalPages = Math.ceil(versions.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const currentVersions = versions.slice(startIndex, endIndex);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
    }
  };

  const handleViewVersion = (versionItem: any) => {
      if (versionItem.isCurrent && activeTemplate?.status === 'Draft') {
          onSelectVersion(activeTemplate!, versionItem.version);
      } else {
          const snapshotTemplate: Template = {
              ...activeTemplate!,
              version: versionItem.version,
              status: versionItem.status as Template['status'],
              lastUpdated: versionItem.lastUpdated,
              updatedBy: versionItem.updatedBy,
              blocks: activeTemplate!.history?.find(h => h.version === versionItem.version)?.blocksSnapshot || activeTemplate!.blocks
          };
          onTestLogic(snapshotTemplate);
      }
  };

  if (!activeTemplate) {
      return (
          <div className="text-center py-20">
              <p className="text-gray-500">No templates available.</p>
              <button onClick={onCreateTemplate} className="mt-4 text-indigo-600 font-medium">Create your first template</button>
          </div>
      );
  }

  return (
    <div>
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-8">
        <div>
          <h1 className="text-4xl font-serif font-bold text-gray-900 tracking-tight">{activeTemplate.name}</h1>
          <p className="text-gray-500 mt-2 flex items-center gap-2">
            <span className="font-mono text-xs bg-gray-100 px-2 py-0.5 rounded border border-gray-200">{activeTemplate.id.toUpperCase()}</span>
          </p>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => onOpenSiteDetails(activeTemplate)}
            className="px-5 py-2.5 rounded-lg border border-gray-200 bg-white text-gray-700 text-sm font-medium hover:bg-gray-50 hover:border-gray-300 transition-all flex items-center gap-2 shadow-sm"
          >
            <Building2 className="w-4 h-4 text-gray-500" /> Manage Sites
          </button>

          <button 
            onClick={() => onCreateDraft?.(activeTemplate)}
            className="px-5 py-2.5 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold transition-all flex items-center gap-2 shadow-md hover:shadow-lg"
          >
            <Plus className="w-4 h-4" /> Create Draft
          </button>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-6 pt-2">
        <div className="flex flex-col gap-1 w-full sm:w-[320px] sm:ml-auto">
          <div className="relative">
            <input 
              type="text" 
              placeholder="Search versions..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-9 pr-4 py-2 rounded-md border border-gray-200 bg-white text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 transition-all placeholder:text-gray-400 shadow-sm"
            />
            <Search className="w-4 h-4 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-[0_1px_3px_rgba(0,0,0,0.1)] border border-gray-200 overflow-hidden flex flex-col">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-100">
            <thead className="bg-gray-50/50">
