               <Settings className="w-3.5 h-3.5" /> Settings
             </button>
          </div>
        </div>

        {/* Actions - Always Visible CTAs */}
        <div className="flex items-center gap-3">
          <button 
            onClick={onTestLogic}
            className="px-4 py-2 rounded-lg border border-gray-200 bg-white text-gray-700 text-sm font-medium hover:bg-gray-50 hover:border-gray-300 transition-all flex items-center gap-2 shadow-sm"
          >
            <Beaker className="w-4 h-4 text-gray-500" /> Test Logic
          </button>

          <button
            onClick={onSaveDraft}
            className="px-4 py-2 rounded-lg border border-gray-200 bg-white text-gray-700 text-sm font-medium hover:bg-gray-50 hover:border-gray-300 transition-all flex items-center gap-2 shadow-sm"
          >
            <Save className="w-4 h-4 text-gray-500" /> Save Draft
          </button>

          <button 
            onClick={onPublish}
            className="px-5 py-2 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-medium transition-all flex items-center gap-2 shadow-md hover:shadow-lg"
          >
            {isPublishedOrRollingOut ? <Building2 className="w-4 h-4" /> : <UploadCloud className="w-4 h-4" />}
            {isPublishedOrRollingOut ? 'Site List' : 'Publish'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Plus } from 'lucide-react';
import { Header } from './components/Header';
import { BlockList } from './components/BlockList';
import { FilterBar } from './components/FilterBar';
import { BlockModal } from './components/BlockModal';
import { HistoryModal } from './components/HistoryModal';
import { LogicModal } from './components/LogicModal';
import { TemplateList } from './components/TemplateList';
import { TestLogicModal } from './components/TestLogicModal';
import { NewTemplateModal } from './components/NewTemplateModal';
import { NewSkeletonModal } from './components/NewSkeletonModal';
import { PublishModal } from './components/PublishModal';
import { TemplateSettingsModal } from './components/TemplateSettingsModal';
import { SiteDetailsModal } from './components/SiteDetailsModal';
import { AuditLogModal } from './components/AuditLogModal';
import { AICloneModal, AICloneOption } from './components/AICloneModal';
import { MOCK_TEMPLATES, TEMPLATE_SKELETONS, getMockSitesForTemplate } from './constants';
import { Template, Block, BlockType, LogicRule, Site, Skeleton, BlockHistoryEntry } from './types';

export function App() {
  const [view, setView] = useState<'list' | 'builder'>('list');
  const [templates, setTemplates] = useState<Template[]>(MOCK_TEMPLATES || []);
  const [template, setTemplate] = useState<Template>(() => {
    return (templates && templates.length > 0) ? templates[0] : null as any;
  });
  const [viewingVersion, setViewingVersion] = useState<string | null>(null);
  const [skeletons, setSkeletons] = useState<Skeleton[]>(TEMPLATE_SKELETONS || []);

  const [expandedBlockIds, setExpandedBlockIds] = useState<Set<string>>(new Set());

  const [sitesByTemplate, setSitesByTemplate] = useState<Record<string, Site[]>>(() => {
    const initialSites: Record<string, Site[]> = {};
    if (MOCK_TEMPLATES) {
      MOCK_TEMPLATES.forEach(t => {
        initialSites[t.id] = getMockSitesForTemplate(t.id, t.version);
      });
    }
    return initialSites;
  });

  const [editingBlock, setEditingBlock] = useState<Block | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [historyBlock, setHistoryBlock] = useState<Block | null>(null);

  const [isLogicModalOpen, setIsLogicModalOpen] = useState(false);
  const [logicBlockId, setLogicBlockId] = useState<string | null>(null);

  const [isTestLogicOpen, setIsTestLogicOpen] = useState(false);
  const [isNewTemplateModalOpen, setIsNewTemplateModalOpen] = useState(false);
  const [isNewSkeletonModalOpen, setIsNewSkeletonModalOpen] = useState(false);
  const [editingSkeleton, setEditingSkeleton] = useState<Skeleton | null>(null);
  const [isPublishModalOpen, setIsPublishModalOpen] = useState(false);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const [isSiteDetailsModalOpen, setIsSiteDetailsModalOpen] = useState(false);
  const [isAuditLogOpen, setIsAuditLogOpen] = useState(false);
  const [isAICloneModalOpen, setIsAICloneModalOpen] = useState(false);
  const [blockToCloneId, setBlockToCloneId] = useState<string | null>(null);
  const [showSaveNotification, setShowSaveNotification] = useState(false);

  const [filterType, setFilterType] = useState<BlockType | 'All'>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [showMismatchOnly, setShowMismatchOnly] = useState(false);
  const [showDerived, setShowDerived] = useState(true);

  const headerTemplate = useMemo(() => {
    if (!template) return null as any;
    if (viewingVersion && viewingVersion !== template.version) {
       const historyItem = template.history?.find(h => h.version === viewingVersion);
       if (historyItem) {
          let computedStatus: Template['status'] = 'Archived';
          if (template.status === 'Draft' && viewingVersion === template.previousVersion) {
              computedStatus = 'Published'; 
          }

          return {
              ...template,
              version: viewingVersion,
              lastUpdated: historyItem.lastUpdated,
              updatedBy: historyItem.updatedBy,
              blocks: historyItem.blocksSnapshot,
              status: computedStatus
          };
       }
    }
    return template;
  }, [template, viewingVersion]);

  const isReadOnlyMode = !!viewingVersion || (template && template.status !== 'Draft');

  const updateTemplateForFirstEdit = (templateToUpdate: Template): Template => {
    if (templateToUpdate.status !== 'Draft') {
        const [major] = templateToUpdate.version.split('.').map(Number);
        const newVersion = `${major}.${1}`;

        const historyEntry = {
            version: templateToUpdate.version,
            lastUpdated: templateToUpdate.lastUpdated,
            updatedBy: templateToUpdate.updatedBy || 'Unknown',
            blocksSnapshot: templateToUpdate.blocks
        };

        return {
            ...templateToUpdate,
            status: 'Draft',
            version: newVersion,
            previousVersion: templateToUpdate.version,
            lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
            updatedBy: 'Liam Alexander',
            history: [historyEntry, ...(templateToUpdate.history || [])]
        };
    }
    return templateToUpdate;
  };

  const handleUnlockTemplate = () => {
    if (template.status !== 'Draft') {
        const newTemplate = updateTemplateForFirstEdit(template);
        setTemplate(newTemplate);
        setTemplates(prev => prev.map(t => t.id === newTemplate.id ? newTemplate : t));
    }
    setViewingVersion(null);
  };

  const handleCreateDraftFromList = (t: Template) => {
      const newTemplate = updateTemplateForFirstEdit(t);
      setTemplate(newTemplate);
      setTemplates(prev => prev.map(old => old.id === newTemplate.id ? newTemplate : old));
      setView('builder');
      setViewingVersion(null);
  };

  const handleSaveDraft = () => {
     const currentDate = new Date().toLocaleDateString('en-GB').replace(/\//g, '.');
     const historyEntry = {
        version: template.version,
        lastUpdated: template.lastUpdated,
        updatedBy: template.updatedBy || 'Liam Alexander',
        blocksSnapshot: template.blocks
     };

     const [major, minor] = template.version.split('.').map(Number);
     const safeMajor = isNaN(major) ? 1 : major;
     const safeMinor = isNaN(minor) ? 0 : minor;
     const newVersion = `${safeMajor}.${safeMinor + 1}`;

     const updatedTemplate: Template = {
         ...template,
         version: newVersion,
         lastUpdated: currentDate,
         history: [historyEntry, ...(template.history || [])]
     };

     setTemplate(updatedTemplate);
     setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));

     setViewingVersion(null);
     setShowSaveNotification(true);
     setTimeout(() => setShowSaveNotification(false), 3000);
  };

  const handleConfirmPublish = (templateId: string) => {
    const publishLogic = (t: Template): Template => {
      if (t.id === templateId && t.status === 'Draft') {
        const currentVersionNumber = parseFloat(t.version);
        const newMajorVersion = isNaN(currentVersionNumber) ? '1.0' : `${Math.floor(currentVersionNumber) + 1}.0`;

        const publishedBlocks = t.blocks.map(block => ({
          ...block,
          editedInDraft: false,
          versionAtSessionStart: block.version,
        }));

        return {
          ...t,
          status: 'Rolling Out',
          version: newMajorVersion,
          previousVersion: t.version,
          blocks: publishedBlocks,
        };
      }
      return t;
    };

    setTemplates(prev => prev.map(publishLogic));
    if (template.id === templateId && template.status === 'Draft') {
      setTemplate(prev => publishLogic(prev));
    }
    setViewingVersion(null);
    setIsPublishModalOpen(false);
  };

  const handleUpdateSites = (templateId: string, siteIdsToUpdate: string[]) => {
     setSitesByTemplate(prev => {
        const sites = prev[templateId] || [];
        const currentTemplate = templates.find(t => t.id === templateId);
        if (!currentTemplate) return prev;

        const updatedSites = sites.map(site => {
           if (siteIdsToUpdate.includes(site.id)) {
             return { ...site, version: currentTemplate.version, lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.') };
           }
           return site;
        });

        const allSitesUpdated = updatedSites.every(s => s.version === currentTemplate.version);

        if (allSitesUpdated && currentTemplate.status === 'Rolling Out') {
             setTimeout(() => {
                 const updateStatus = (t: Template) => t.id === templateId ? { ...t, status: 'Published' as const } : t;
                 setTemplates(prevTemplates => prevTemplates.map(updateStatus));
                 if (template.id === templateId) {
                    setTemplate(prev => ({ ...prev, status: 'Published' }));
                 }
             }, 0);
        }

        return { ...prev, [templateId]: updatedSites };
     });
     setIsPublishModalOpen(false);
  };

  const handleBack = () => {
    setView('list');
    setViewingVersion(null);
    setFilterType('All');
    setSearchQuery('');
    setShowDerived(true);
  };

  const handleSelectTemplate = (t: Template) => {
    setTemplate(t);
    setView('builder');
    setViewingVersion(null);
  };

  const handleSelectVersion = (t: Template, v: string) => {
      setTemplate(t);
      setView('builder');
      setViewingVersion(v);
  };

  const handleCreateTemplate = (name: string, skeletonId: string) => {
    const skeleton = skeletons.find(s => s.id === skeletonId);
    if (!skeleton) return;

    const newTemplate: Template = {
      id: `tmpl_${Date.now()}`,
      name: name,
      skeleton: skeleton.name,
      version: '0.1',
      previousVersion: '0.0',
      lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
      updatedBy: 'Liam Alexander',
      status: 'Draft',
      blocks: skeleton.blocks.map((b, i) => ({
        id: `blk_${Date.now()}_${i}`,
        type: b.type,
        contentName: b.contentName,
        content: b.content,
        version: '0.1',
        lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
        hasEditHistory: false,
        history: [],
        isSyncing: false,
        rules: []
      })),
      history: []
    };

    setTemplates([newTemplate, ...templates]);
    setSitesByTemplate(prev => ({ ...prev, [newTemplate.id]: [] }));
    setIsNewTemplateModalOpen(false);
    handleSelectTemplate(newTemplate);
  };

  const handleCreateSkeleton = (name: string, description: string, blocks: { type: BlockType; name: string; content: string }[]) => {
     const newSkeleton: Skeleton = {
        id: `sk_${Date.now()}`,
        name,
        description,
        status: 'Active',
        blocks: blocks.map(b => ({
           type: b.type,
           contentName: b.name,
           content: b.content,
           version: '1.0',
           lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
           hasEditHistory: false,
           history: [],
           isSyncing: false,
           rules: []
        }))
     };
     setSkeletons([...skeletons, newSkeleton]);
     setIsNewSkeletonModalOpen(false);
  };

  const handleEditSkeleton = (skeleton: Skeleton) => {
     setEditingSkeleton(skeleton);
     setIsNewSkeletonModalOpen(true);
  };

  const handleArchiveSkeleton = (skeletonId: string) => {
     setSkeletons(prev => prev.map(s => s.id === skeletonId ? { ...s, status: 'Archived' } : s));
  };

  const handleSaveSkeleton = (name: string, description: string, blocks: { type: BlockType; name: string; content: string }[]) => {
      if (editingSkeleton) {
        setSkeletons(prev => prev.map(s => s.id === editingSkeleton.id ? {
           ...s,
           name,
           description,
           blocks: blocks.map(b => ({
               type: b.type,
               contentName: b.name,
               content: b.content,
               version: '1.0',
               lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
               hasEditHistory: false,
               history: [],
               isSyncing: false,
               rules: []
           }))
        } : s));
        setEditingSkeleton(null);
        setIsNewSkeletonModalOpen(false);
      } else {
        handleCreateSkeleton(name, description, blocks);
      }
  };

  const handleArchiveTemplate = (templateId: string) => {
     setTemplates(prev => prev.map(t => t.id === templateId ? { ...t, status: 'Archived' } : t));
  };

  const handleSaveTemplateSettings = (templateId: string, newName: string) => {
     setTemplates(prev => prev.map(t => t.id === templateId ? { ...t, name: newName } : t));
     if (template.id === templateId) {
        setTemplate(prev => ({ ...prev, name: newName }));
     }
  };

  const handleToggleExpand = (id: string) => {
    setExpandedBlockIds(prev => {
        const next = new Set(prev);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        return next;
    });
  };

  const handleDeleteBlock = (id: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const updatedBlocks = currentTemplate.blocks.filter(b => b.id !== id);
    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
  };

  const handleDuplicateBlock = (id: string) => {
    setBlockToCloneId(id);
    setIsAICloneModalOpen(true);
  };

  const handleAIClone = (option: AICloneOption) => {
    if (!blockToCloneId) return;

    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const blockToDuplicate = currentTemplate.blocks.find(b => b.id === blockToCloneId);
    if (blockToDuplicate) {
      let transformedContent = blockToDuplicate.content || '';
      let suffix = '';

      switch (option) {
        case 'simplify':
          transformedContent = transformedContent + "\n\n[AI: Simplified Content]";
          suffix = ' (Simplified)';
          break;
        case 'past_tense':
          transformedContent = transformedContent.replace(/will be/g, "was").replace(/is/g, "was") + "\n\n[AI: Converted to Past Tense]";
          suffix = ' (Past Tense)';
          break;
        case 'future_tense':
          transformedContent = transformedContent.replace(/was/g, "will be").replace(/is/g, "will be") + "\n\n[AI: Converted to Future Tense]";
          suffix = ' (Future Tense)';
          break;
        case 'formal':
          transformedContent = "The aforementioned " + transformedContent.toLowerCase() + "\n\n[AI: Formal Tone Applied]";
          suffix = ' (Formal)';
          break;
        case 'standard':
        default:
          break;
      }

      const newBlock: Block = {
        ...blockToDuplicate,
        id: `blk_${Date.now()}`,
        contentName: `Copy of ${blockToDuplicate.contentName}${suffix}`,
        content: transformedContent,
        version: blockToDuplicate.version,
        isCloned: true,
        clonedFrom: blockToDuplicate.id,
        derivedFromVersion: blockToDuplicate.version,
        subLabel: `Derived from ${blockToDuplicate.contentName} ${blockToDuplicate.version}${option !== 'standard' ? ` via AI (${option})` : ''}`,
        rules: [],
        editedInDraft: true,
        isDraftCopy: true,
        associatedDomainIds: blockToDuplicate.associatedDomainIds ? [...blockToDuplicate.associatedDomainIds] : [],
        history: [{
            version: blockToDuplicate.version,
            templateVersion: currentTemplate.version,
            updatedAt: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
            editedBy: 'Liam Alexander',
            changeDescription: `Created via ${option === 'standard' ? 'duplication' : 'AI transformation'}`,
            contentSnapshot: transformedContent
        }]
      };

      const index = currentTemplate.blocks.findIndex(b => b.id === blockToCloneId);
      const newBlocks = [...currentTemplate.blocks];
      newBlocks.splice(index + 1, 0, newBlock);

      const updatedTemplate = { ...currentTemplate, blocks: newBlocks };
      setTemplate(updatedTemplate);
      setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
    }

    setIsAICloneModalOpen(false);
    setBlockToCloneId(null);
  };

  const handleUpdateNote = (blockId: string, note: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
       currentTemplate = updateTemplateForFirstEdit(template);
       setTemplate(currentTemplate);
       setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const updatedBlocks = currentTemplate.blocks.map(b => 
      b.id === blockId ? { ...b, notes: note } : b
    );

    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
  };

  const handleReorderBlocks = (draggedBlockId: string, targetBlockId: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const blocks = [...currentTemplate.blocks];
    const draggedBlock = blocks.find(b => b.id === draggedBlockId);
    if (!draggedBlock) return;

    const blocksWithoutDragged = blocks.filter(b => b.id !== draggedBlockId);
    const targetIndex = blocksWithoutDragged.findIndex(b => b.id === targetBlockId);
    if (targetIndex === -1) return;

    blocksWithoutDragged.splice(targetIndex, 0, draggedBlock);

    const updatedTemplate = { ...currentTemplate, blocks: blocksWithoutDragged };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
  };

  const handleEditContent = (block: Block) => {
    setEditingBlock(block);
    setIsModalOpen(true);
  };

  const handleSaveBlock = (blockId: string, name: string, type: BlockType, content: string, rules: LogicRule[], associatedDomainIds?: string[]) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const [tmplMajor] = currentTemplate.version.split('.').map(Number);
    const currentBlock = currentTemplate.blocks.find(b => b.id === blockId);
    let newVersion = '1.0';
    if (currentBlock) {
        const [blkMajor, blkMinor] = currentBlock.version.split('.').map(Number);
        const safeBlkMajor = isNaN(blkMajor) ? 1 : blkMajor;
        const safeBlkMinor = isNaN(blkMinor) ? 0 : blkMinor;
        const safeTmplMajor = isNaN(tmplMajor) ? 1 : tmplMajor;

        if (safeBlkMajor === safeTmplMajor) {
            newVersion = `${safeBlkMajor}.${safeBlkMinor + 1}`;
        } else {
            newVersion = `${safeTmplMajor}.1`;
        }
    }

    const currentDate = new Date().toLocaleDateString('en-GB').replace(/\//g, '.');

    const updatedBlocks = currentTemplate.blocks.map(b => {
      if (b.id === blockId) {
        const historyEntry: BlockHistoryEntry = {
          version: b.version,
          templateVersion: currentTemplate.version,
          updatedAt: b.lastUpdated,
          editedBy: 'Liam Alexander',
          changeDescription: b.content !== content ? 'Content updated' : 'Properties updated',
          contentSnapshot: b.content || ''
        };

        return {
          ...b,
          contentName: name,
          type,
          content,
          rules,
          associatedDomainIds,
          version: newVersion,
          lastUpdated: currentDate,
          history: [historyEntry, ...b.history],
          editedInDraft: true,
          hasEditHistory: true
        };
      }
      return b;
    });

    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
    setIsModalOpen(false);
    setEditingBlock(null);
  };

  const handleShowHistory = (block: Block) => {
    setHistoryBlock(block);
    setIsHistoryOpen(true);
  };

  const handleAddLogic = (blockId: string) => {
    setLogicBlockId(blockId);
    setIsLogicModalOpen(true);
  };

  const handleSaveLogicRule = (ruleData: Omit<LogicRule, 'id'>) => {
    if (!logicBlockId) return;

    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const newRule: LogicRule = {
        ...ruleData,
        id: `rule_${Date.now()}`
    };

    const updatedBlocks = currentTemplate.blocks.map(b => {
        if (b.id === logicBlockId) {
             const [major, minor] = b.version.split('.').map(Number);
             const safeMajor = isNaN(major) ? 1 : major;
             const safeMinor = isNaN(minor) ? 0 : minor;
             const newVersion = `${safeMajor}.${safeMinor + 1}`;

             const historyEntry: BlockHistoryEntry = {
                 version: b.version,
                 templateVersion: currentTemplate.version,
                 updatedAt: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 editedBy: 'Liam Alexander',
                 changeDescription: 'Logic rule added',
                 contentSnapshot: b.content || ''
             };

             return {
                 ...b,
                 rules: [...b.rules, newRule],
                 version: newVersion,
                 lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 history: [historyEntry, ...b.history],
                 editedInDraft: true,
                 hasEditHistory: true
             };
        }
        return b;
    });

    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
    setIsLogicModalOpen(false);
    setLogicBlockId(null);
  };

  const handleDeleteLogic = (blockId: string, ruleId: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const updatedBlocks = currentTemplate.blocks.map(b => {
        if (b.id === blockId) {
             const [major, minor] = b.version.split('.').map(Number);
             const safeMajor = isNaN(major) ? 1 : major;
             const safeMinor = isNaN(minor) ? 0 : minor;
             const newVersion = `${safeMajor}.${safeMinor + 1}`;

             const historyEntry: BlockHistoryEntry = {
                 version: b.version,
                 templateVersion: currentTemplate.version,
                 updatedAt: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 editedBy: 'Liam Alexander',
                 changeDescription: 'Logic rule removed',
                 contentSnapshot: b.content || ''
             };

             return {
                 ...b,
                 rules: b.rules.filter(r => r.id !== ruleId),
                 version: newVersion,
                 lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 history: [historyEntry, ...b.history],
                 editedInDraft: true,
                 hasEditHistory: true
             };
        }
        return b;
    });

    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
  };

  const handleToggleDisable = (blockId: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const updatedBlocks = currentTemplate.blocks.map(b => {
        if (b.id === blockId) {
             const [major, minor] = b.version.split('.').map(Number);
             const safeMajor = isNaN(major) ? 1 : major;
             const safeMinor = isNaN(minor) ? 0 : minor;
             const newVersion = `${safeMajor}.${safeMinor + 1}`;
             const newDisabledState = !b.isDisabled;

             const historyEntry: BlockHistoryEntry = {
                 version: b.version,
                 templateVersion: currentTemplate.version,
                 updatedAt: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 editedBy: 'Liam Alexander',
                 changeDescription: newDisabledState ? 'Block disabled' : 'Block enabled',
                 contentSnapshot: b.content || ''
             };

             return {
                 ...b,
                 isDisabled: newDisabledState,
                 version: newVersion,
                 lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 history: [historyEntry, ...b.history],
                 editedInDraft: true,
                 hasEditHistory: true
             };
        }
        return b;
    });

    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
  };

  const handleAddNewBlock = (afterBlockId?: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const newBlock: Block = {
        id: `blk_${Date.now()}`,
        type: 'Universal',
        contentName: 'Add content',
        content: '',
        version: '0.1',
        lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
        hasEditHistory: false,
        history: [],
        isSyncing: false,
        rules: []
    };

    let newBlocks = [...currentTemplate.blocks];
    if (afterBlockId) {
        const index = newBlocks.findIndex(b => b.id === afterBlockId);
        if (index !== -1) {
            newBlocks.splice(index + 1, 0, newBlock);
        } else {
            newBlocks.push(newBlock);
        }
    } else {
        newBlocks.push(newBlock);
    }

    const updatedTemplate = {
        ...currentTemplate,
        blocks: newBlocks
    };

    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
    setEditingBlock(newBlock);
    setIsModalOpen(true);
  };

  const filteredBlocks = useMemo(() => {
    if (!headerTemplate || !headerTemplate.blocks) return [];
    let blocks = headerTemplate.blocks;

    if (filterType !== 'All') {
      blocks = blocks.filter(b => b.type === filterType);
    }

    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      blocks = blocks.filter(b => 
        b.contentName.toLowerCase().includes(q) || 
        (b.content && b.content.toLowerCase().includes(q))
      );
    }

    if (showMismatchOnly) {
       blocks = blocks.filter(b => {
           if (!b.isCloned || !b.clonedFrom) return false;
           const parent = headerTemplate.blocks.find(p => p.id === b.clonedFrom);
           return parent && parent.version !== b.derivedFromVersion;
       });
    }

    if (!showDerived && !showMismatchOnly && !searchQuery) {
        blocks = blocks.filter(b => !b.isCloned);
    }

    return blocks;
  }, [headerTemplate, filterType, searchQuery, showMismatchOnly, showDerived]);

  const blocksToRender = useMemo(() => {
      return filteredBlocks.map(b => ({
          ...b,
          isExpanded: expandedBlockIds.has(b.id)
      }));
  }, [filteredBlocks, expandedBlockIds]);

  const areAllExpanded = useMemo(() => {
    if (filteredBlocks.length === 0) return false;
    return filteredBlocks.every(b => expandedBlockIds.has(b.id));
  }, [filteredBlocks, expandedBlockIds]);

  const handleToggleExpandAll = () => {
    if (areAllExpanded) {
       setExpandedBlockIds(prev => {
          const next = new Set(prev);
          filteredBlocks.forEach(b => next.delete(b.id));
          return next;
       });
    } else {
       setExpandedBlockIds(prev => {
          const next = new Set(prev);
          filteredBlocks.forEach(b => next.add(b.id));
          return next;
       });
    }
  };

  const latestPublishedVersion = useMemo(() => {
     if (!template) return null;
     if (template.status === 'Published' || template.status === 'Rolling Out' || template.status === 'Archived') {
         return template.version;
     }

     const candidates = new Set<string>();
     if (template.previousVersion) candidates.add(template.previousVersion);
     if (template.history) {
         template.history.forEach(h => candidates.add(h.version));
     }

     const publishedVersions = Array.from(candidates)
         .filter(v => v.endsWith('.0'))
         .sort((a, b) => parseFloat(b) - parseFloat(a));

     return publishedVersions.length > 0 ? publishedVersions[0] : null;
  }, [template]);

  const canReorder = !isReadOnlyMode && filterType === 'All' && !searchQuery && !showMismatchOnly && showDerived;

  if (!template) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center p-8">
           <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
           <p className="text-gray-500">Loading templates...</p>
        </div>
      </div>
    );
  }

  if (view === 'list') {
    return (
      <div className="min-h-screen bg-gray-50/50 p-8 font-sans">
        <div className="max-w-7xl mx-auto">
          <TemplateList 
            templates={templates}
            skeletons={skeletons}
            sitesByTemplate={sitesByTemplate}
            onSelectTemplate={handleSelectTemplate}
            onSelectVersion={handleSelectVersion}
            onCreateTemplate={() => setIsNewTemplateModalOpen(true)}
            onCreateSkeleton={() => setIsNewSkeletonModalOpen(true)}
            onEditSkeleton={handleEditSkeleton}
            onArchiveSkeleton={handleArchiveSkeleton}
            onTestLogic={(t) => {
              setTemplate(t);
              setIsTestLogicOpen(true);
            }}
            onArchive={handleArchiveTemplate}
            onUpdateSite={(tId, sId) => {
                 setSitesByTemplate(prev => {
                     const list = prev[tId] || [];
                     const tmpl = templates.find(t => t.id === tId);
                     return {
                         ...prev,
                         [tId]: list.map(s => s.id === sId && tmpl ? { ...s, version: tmpl.version } : s)
                     };
                 });
            }}
            onOpenSiteDetails={(t) => {
               if(t) setTemplate(t);
               setIsSiteDetailsModalOpen(true);
            }}
            onCreateDraft={handleCreateDraftFromList}
          />
        </div>

        {isNewTemplateModalOpen && (
          <NewTemplateModal 
            isOpen={isNewTemplateModalOpen} 
            onClose={() => setIsNewTemplateModalOpen(false)}
            onCreate={handleCreateTemplate}
            skeletons={skeletons}
          />
        )}

        {isNewSkeletonModalOpen && (
          <NewSkeletonModal 
            isOpen={isNewSkeletonModalOpen}
            onClose={() => { setIsNewSkeletonModalOpen(false); setEditingSkeleton(null); }}
            onSave={handleSaveSkeleton}
            initialSkeleton={editingSkeleton}
          />
        )}

        {isTestLogicOpen && (
           <TestLogicModal 
             isOpen={isTestLogicOpen}
             onClose={() => setIsTestLogicOpen(false)}
             template={template}
           />
        )}

        {isSiteDetailsModalOpen && (
           <SiteDetailsModal
             isOpen={isSiteDetailsModalOpen}
             onClose={() => setIsSiteDetailsModalOpen(false)}
             template={template}
             allTemplates={templates}
             sites={sitesByTemplate[template.id] || []}
             onUpdateSites={handleUpdateSites}
             onSelectTemplate={setTemplate}
           />
        )}
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50/50 font-sans pb-20">

      <div className="bg-white border-b border-gray-200 sticky top-0 z-30">
         <div className="max-w-7xl mx-auto px-6 py-4">
            <Header 
              template={headerTemplate}
              selectedVersion={viewingVersion || template.version}
              isReadOnly={isReadOnlyMode}
              realStatus={template.status}
              latestPublishedVersion={latestPublishedVersion}
              onBack={handleBack}
              onTestLogic={() => setIsTestLogicOpen(true)}
              onPublish={() => setIsPublishModalOpen(true)}
              onOpenSettings={() => setIsSettingsModalOpen(true)}
              onUnlock={handleUnlockTemplate}
              onSaveDraft={handleSaveDraft}
              onOpenAuditLog={() => setIsAuditLogOpen(true)}
            />
         </div>
      </div>

      <div className="max-w-7xl mx-auto px-6 py-6">

        <FilterBar 
          selectedType={filterType}
          onTypeChange={setFilterType}
          searchQuery={searchQuery}
          onSearchChange={setSearchQuery}
          showMismatchOnly={showMismatchOnly}
          onToggleMismatch={() => setShowMismatchOnly(!showMismatchOnly)}
          showDerived={showDerived}
          onToggleDerived={() => setShowDerived(!showDerived)}
          areAllExpanded={areAllExpanded}
          onToggleExpandAll={handleToggleExpandAll}
        />

        <BlockList 
          blocks={blocksToRender} 
          allBlocks={headerTemplate.blocks}
          isReadOnly={isReadOnlyMode}
          onToggleExpand={handleToggleExpand}
          onDeleteBlock={handleDeleteBlock}
          onDuplicateBlock={handleDuplicateBlock}
          onEditContent={handleEditContent}
          onShowHistory={handleShowHistory}
          onAddLogic={handleAddLogic}
          onDeleteLogic={handleDeleteLogic}
          onRevertBlock={() => {}} 
          onToggleDisable={handleToggleDisable}
          onReorderBlocks={handleReorderBlocks}
          onUpdateNote={handleUpdateNote}
          onAddBlock={handleAddNewBlock}
          canReorder={canReorder}
        />

      </div>

      {isModalOpen && (
        <BlockModal 
          isOpen={isModalOpen}
          onClose={() => { setIsModalOpen(false); setEditingBlock(null); }}
          onSave={handleSaveBlock}
          initialBlock={editingBlock}
          existingBlocks={headerTemplate.blocks}
          parentBlock={editingBlock?.clonedFrom ? headerTemplate.blocks.find(b => b.id === editingBlock.clonedFrom) : undefined}
        />
      )}

      {isHistoryOpen && (
        <HistoryModal 
          isOpen={isHistoryOpen}
          onClose={() => setIsHistoryOpen(false)}
          block={historyBlock}
          currentTemplateVersion={headerTemplate.version}
        />
      )}

      {isLogicModalOpen && (
        <LogicModal 
          isOpen={isLogicModalOpen}
          onClose={() => setIsLogicModalOpen(false)}
          onSave={handleSaveLogicRule}
        />
      )}

      {isTestLogicOpen && (
         <TestLogicModal 
           isOpen={isTestLogicOpen}
           onClose={() => setIsTestLogicOpen(false)}
           template={headerTemplate}
         />
      )}

      {isPublishModalOpen && (
         <PublishModal 
           isOpen={isPublishModalOpen}
           onClose={() => setIsPublishModalOpen(false)}
           templateId={template.id}
           templateName={template.name}
           currentVersion={template.version}
           status={template.status}
           sites={sitesByTemplate[template.id] || []}
           onConfirm={handleConfirmPublish}
           onConfirmUpdates={handleUpdateSites}
         />
      )}

      {isSettingsModalOpen && (
         <TemplateSettingsModal
            isOpen={isSettingsModalOpen}
            onClose={() => setIsSettingsModalOpen(false)}
            onSave={handleSaveTemplateSettings}
            template={template}
         />
      )}

      {isAuditLogOpen && (
        <AuditLogModal 
          isOpen={isAuditLogOpen}
          onClose={() => setIsAuditLogOpen(false)}
          template={headerTemplate}
        />
      )}

      {isAICloneModalOpen && blockToCloneId && (
        <AICloneModal 
          isOpen={isAICloneModalOpen}
          onClose={() => { setIsAICloneModalOpen(false); setBlockToCloneId(null); }}
          onConfirm={handleAIClone}
          blockName={headerTemplate.blocks.find(b => b.id === blockToCloneId)?.contentName || 'Unknown Block'}
        />
      )}

      {showSaveNotification && (
        <div className="fixed bottom-6 right-6 bg-gray-900 text-white px-4 py-3 rounded-lg shadow-lg flex items-center gap-3 animate-in fade-in slide-in-from-bottom-4 z-50">
          <div className="bg-emerald-500 rounded-full p-1">
            <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <div>
            <h4 className="font-medium text-sm">Draft Saved</h4>
            <p className="text-xs text-gray-400">Version {template.version} created</p>
          </div>
        </div>
      )}

    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { 
  Plus, 
  Search,
  ChevronLeft,
  ChevronRight,
  Building2,
  Clock,
  User,
  Eye,
  PenLine
} from 'lucide-react';
import { Template, Site, Skeleton } from '../types';

interface TemplateListProps {
  templates: Template[];
  skeletons: Skeleton[];
  sitesByTemplate: Record<string, Site[]>;
  onSelectTemplate: (template: Template) => void;
  onSelectVersion: (template: Template, version: string) => void;
  onCreateTemplate: () => void;
  onCreateSkeleton: () => void;
  onEditSkeleton: (skeleton: Skeleton) => void;
  onArchiveSkeleton: (skeletonId: string) => void;
  onTestLogic: (template: Template) => void;
  onArchive: (templateId: string) => void;
  onUpdateSite: (templateId: string, siteId: string) => void;
  onOpenSiteDetails: (template?: Template) => void;
  onCreateDraft?: (template: Template) => void;
}

const getStatusStyles = (status: string) => {
  switch (status) {
    case 'Published':
      return 'text-emerald-700 bg-emerald-50 border-emerald-200 font-bold';
    case 'Rolling Out':
      return 'text-purple-700 bg-purple-50 border-purple-200 font-bold';
    case 'Draft':
      return 'text-amber-700 bg-amber-50 border-amber-200 font-bold';
    case 'Archived':
      return 'text-gray-700 bg-gray-50 border-gray-200';
    case 'Snapshot':
      return 'text-slate-600 bg-slate-100 border-slate-200';
    default:
      return 'text-gray-700 bg-gray-50 border-gray-200';
  }
};

interface VersionRowProps {
  version: string;
  status: string;
  lastUpdated: string;
  updatedBy: string;
  isCurrent: boolean;
  onView: () => void;
}

const VersionRow: React.FC<VersionRowProps> = ({ 
  version, 
  status, 
  lastUpdated, 
  updatedBy, 
  isCurrent, 
  onView
}) => {
  const isDraft = status === 'Draft';

  return (
    <tr className={`group transition-colors hover:bg-gray-50/50 ${isCurrent ? 'bg-indigo-50/10' : ''}`}>
      <td className="px-6 py-4 whitespace-nowrap">
        <button 
          onClick={(e) => { e.stopPropagation(); onView(); }}
          className="flex items-center gap-2 group/ver outline-none text-left"
        >
           <span className={`font-mono text-sm transition-all ${
             isCurrent 
               ? 'font-bold text-indigo-700' 
               : 'font-semibold text-gray-900 group-hover/ver:text-indigo-600 group-hover/ver:underline'
           }`}>
             v{version}
           </span>
        </button>
      </td>

      <td className="px-6 py-4 whitespace-nowrap">
        <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[10px] uppercase tracking-wider border ${getStatusStyles(status)}`}>
          {status}
        </span>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
          <div className="flex items-center gap-1.5">
             <Clock className="w-3.5 h-3.5 text-gray-400" />
             {lastUpdated}
          </div>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
          <div className="flex items-center gap-1.5">
             <User className="w-3.5 h-3.5 text-gray-400" />
             {updatedBy}
          </div>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-right">
        <div className="flex items-center justify-end gap-2">
            <button
            onClick={(e) => { e.stopPropagation(); onView(); }}
            className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg border text-xs font-medium transition-colors shadow-sm ${
                isDraft
                ? 'border-indigo-200 bg-indigo-50 text-indigo-700 hover:bg-indigo-100'
                : 'border-gray-200 bg-white text-gray-700 hover:bg-gray-50 hover:text-indigo-600'
            }`}
            >
            {isDraft ? <PenLine className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
            {isDraft ? 'Edit' : 'View'}
            </button>
        </div>
      </td>
    </tr>
  );
};

export const TemplateList: React.FC<TemplateListProps> = ({ templates, sitesByTemplate, onSelectVersion, onCreateTemplate, onOpenSiteDetails, onTestLogic, onCreateDraft }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const activeTemplate = templates.length > 0 ? templates[0] : null;

  const versions = useMemo(() => {
      if (!activeTemplate) return [];

      const list = [
          {
              version: activeTemplate.version,
              status: activeTemplate.status,
              lastUpdated: activeTemplate.lastUpdated,
              updatedBy: activeTemplate.updatedBy || 'Unknown',
              isCurrent: true
          }
      ];

      if (activeTemplate.history && activeTemplate.history.length > 0) {
          activeTemplate.history.forEach(h => {
              const verNum = parseFloat(h.version);

              let inferredStatus: string;
              if (activeTemplate.status === 'Draft' && h.version === activeTemplate.previousVersion) {
                  inferredStatus = 'Rolling Out';
              } else {
                  const isMajor = h.version.endsWith('.0');
                  inferredStatus = isMajor ? 'Published' : 'Archived';

                  if (!isMajor || (activeTemplate.previousVersion && parseFloat(h.version) < parseFloat(activeTemplate.previousVersion))) {
                      inferredStatus = 'Archived';
                  }
              }

              list.push({
                  version: h.version,
                  status: inferredStatus,
                  lastUpdated: h.lastUpdated,
                  updatedBy: h.updatedBy,
                  isCurrent: false
              });
          });
      }

      if (searchQuery) {
          return list.filter(v => v.version.includes(searchQuery) || v.updatedBy.toLowerCase().includes(searchQuery.toLowerCase()));
      }

      return list.sort((a, b) => parseFloat(b.version) - parseFloat(a.version));
  }, [activeTemplate, searchQuery]);

  const totalPages = Math.ceil(versions.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const currentVersions = versions.slice(startIndex, endIndex);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
    }
  };

  const handleViewVersion = (versionItem: any) => {
      if (versionItem.isCurrent && activeTemplate?.status === 'Draft') {
          onSelectVersion(activeTemplate!, versionItem.version);
      } else {
          const snapshotTemplate: Template = {
              ...activeTemplate!,
              version: versionItem.version,
              status: versionItem.status as Template['status'],
              lastUpdated: versionItem.lastUpdated,
              updatedBy: versionItem.updatedBy,
              blocks: activeTemplate!.history?.find(h => h.version === versionItem.version)?.blocksSnapshot || activeTemplate!.blocks
          };
          onTestLogic(snapshotTemplate);
      }
  };

  if (!activeTemplate) return null;

  return (
    <div>
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-8">
        <div>
          <h1 className="text-4xl font-serif font-bold text-gray-900 tracking-tight">{activeTemplate.name}</h1>
          <div className="flex items-center gap-3 mt-2">
            <span className="text-sm font-bold text-indigo-600 bg-indigo-50 px-2 py-0.5 rounded border border-indigo-100">Version {activeTemplate.version}</span>
            <span className="text-gray-300">|</span>
            <span className="font-mono text-xs text-gray-400 bg-gray-100 px-2 py-0.5 rounded border border-gray-200">{activeTemplate.id.toUpperCase()}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => onOpenSiteDetails(activeTemplate)}
            className="px-5 py-2.5 rounded-lg border border-gray-200 bg-white text-gray-700 text-sm font-medium hover:bg-gray-50 hover:border-gray-300 transition-all flex items-center gap-2 shadow-sm"
          >
            <Building2 className="w-4 h-4 text-gray-500" /> Manage Sites
          </button>

          <button 
            onClick={() => onCreateDraft?.(activeTemplate)}
            className="px-5 py-2.5 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold transition-all flex items-center gap-2 shadow-md hover:shadow-lg"
          >
            <Plus className="w-4 h-4" /> Create Draft
          </button>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-6">
        <div className="flex flex-col gap-1 w-full sm:w-[320px] sm:ml-auto">
          <div className="relative">
            <input 
              type="text" 
              placeholder="Search versions..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-9 pr-4 py-2 rounded-md border border-gray-200 bg-white text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all placeholder:text-gray-400 shadow-sm"
            />
            <Search className="w-4 h-4 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-100">
            <thead className="bg-gray-50/50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Version</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Status</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Last Updated</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Updated By</th>
                <th scope="col" className="relative px-6 py-3 text-right text-xs font-bold text-gray-500 uppercase tracking-wider">Action</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-100">
              {currentVersions.map((v) => (
                <VersionRow 
                  key={v.version}
                  version={v.version}
                  status={v.status}
                  lastUpdated={v.lastUpdated}
                  updatedBy={v.updatedBy}
                  isCurrent={v.isCurrent}
                  onView={() => handleViewVersion(v)}
                />
              ))}
            </tbody>
          </table>
        </div>

        {versions.length > itemsPerPage && (
          <div className="px-6 py-4 bg-gray-50/50 border-t border-gray-200 flex items-center justify-between text-sm text-gray-600">
            <div>
              Showing <span className="font-semibold">{startIndex + 1}</span> to <span className="font-semibold">{Math.min(endIndex, versions.length)}</span> of <span className="font-semibold">{versions.length}</span>
            </div>
            <div className="flex items-center gap-2">
                <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-1.5 rounded-md border border-gray-300 bg-white hover:bg-gray-50 disabled:opacity-50">
                  <ChevronLeft className="w-4 h-4" />
                </button>
                <span className="text-sm font-medium text-gray-700">Page {currentPage} of {totalPages}</span>
                <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-1.5 rounded-md border border-gray-300 bg-white hover:bg-gray-50 disabled:opacity-50">
                  <ChevronRight className="w-4 h-4" />
                </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React from 'react';
import { ArrowUpRight, Clock, Beaker, ChevronRight, Info, UploadCloud, Building2, Save } from 'lucide-react';
import { Template } from '../types';

interface HeaderProps {
  template: Template;
  selectedVersion: string;
  isReadOnly: boolean;
  realStatus: Template['status'];
  latestPublishedVersion?: string | null;
  onBack: () => void;
  onTestLogic: () => void;
  onPublish: () => void;
  onOpenSettings: () => void;
  onUnlock: () => void;
  onSaveDraft: () => void;
  onOpenAuditLog: () => void;
}

const getStatusStyles = (status: Template['status']) => {
  switch (status) {
    case 'Published':
      return 'bg-emerald-100 text-emerald-800';
    case 'Rolling Out':
      return 'bg-purple-100 text-purple-800';
    case 'Draft':
      return 'bg-amber-100 text-amber-800 font-medium';
    case 'Archived':
      return 'bg-gray-100 text-gray-800';
    default:
      return 'bg-gray-100 text-gray-800';
  }
};

export const Header = ({ template, selectedVersion, onBack, onTestLogic, onPublish, onOpenSettings, onSaveDraft, onOpenAuditLog }: HeaderProps) => {
  const isPublishedOrRollingOut = template.status === 'Published' || template.status === 'Rolling Out';
  const statusToShow = template.status;

  return (
    <div className="mb-8">
      {/* Breadcrumbs */}
      <div className="flex items-center gap-2 text-sm text-gray-500 mb-6 font-medium">
        <button onClick={onBack} className="hover:text-gray-900 transition-colors">Templates</button>
        <ChevronRight className="w-3.5 h-3.5 text-gray-400" />
        <span className="text-gray-900">{template.name}</span>
         <span className="px-2 py-0.5 rounded-full bg-gray-100 text-gray-600 text-xs border border-gray-200 font-mono">
          {template.id.toUpperCase()}
        </span>
      </div>

      <div className="flex flex-col xl:flex-row xl:items-end justify-between gap-6">
        {/* Title and Metadata */}
        <div>
          <div className="flex items-center gap-3 mb-3">
            <h1 className="text-4xl font-serif font-bold text-gray-900 tracking-tight">
              Version {selectedVersion}
            </h1>
            <span className={`px-2.5 py-1 rounded-full text-xs font-semibold tracking-wide ${getStatusStyles(statusToShow)}`}>
              {statusToShow.toUpperCase()}
            </span>
          </div>

          <div className="flex flex-wrap items-center gap-x-6 gap-y-2 text-sm text-gray-500">
             <span className="flex items-center gap-1.5">
               <Clock className="w-4 h-4 text-gray-400" />
               Last updated <span className="text-gray-700 font-medium">{template.lastUpdated}</span>
             </span>
             <button 
               onClick={onOpenAuditLog}
               className="text-indigo-600 hover:text-indigo-800 font-medium flex items-center gap-1 transition-colors"
             >
               Audit Logs <ArrowUpRight className="w-3.5 h-3.5" />
             </button>
             <button 
                onClick={onOpenSettings}
                className="text-indigo-600 hover:text-indigo-800 font-medium flex items-center gap-1.5 transition-colors"
            >
               <Info className="w-3.5 h-3.5" /> Details
             </button>
          </div>
        </div>

        {/* Actions - Always Visible CTAs */}
        <div className="flex items-center gap-3">
          <button 
            onClick={onTestLogic}
            className="px-4 py-2 rounded-lg border border-gray-200 bg-white text-gray-700 text-sm font-medium hover:bg-gray-50 hover:border-gray-300 transition-all flex items-center gap-2 shadow-sm"
          >
            <Beaker className="w-4 h-4 text-gray-500" /> Test Logic
          </button>

          <button
            onClick={onSaveDraft}
            className="px-4 py-2 rounded-lg border border-gray-200 bg-white text-gray-700 text-sm font-medium hover:bg-gray-50 hover:border-gray-300 transition-all flex items-center gap-2 shadow-sm"
          >
            <Save className="w-4 h-4 text-gray-500" /> Save Draft
          </button>

          <button 
            onClick={onPublish}
            className="px-5 py-2 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-medium transition-all flex items-center gap-2 shadow-md hover:shadow-lg"
          >
            {isPublishedOrRollingOut ? <Building2 className="w-4 h-4" /> : <UploadCloud className="w-4 h-4" />}
            {isPublishedOrRollingOut ? 'Site List' : 'Publish'}
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { Plus } from 'lucide-react';
import { Header } from './components/Header';
import { BlockList } from './components/BlockList';
import { FilterBar } from './components/FilterBar';
import { BlockModal } from './components/BlockModal';
import { HistoryModal } from './components/HistoryModal';
import { LogicModal } from './components/LogicModal';
import { TemplateList } from './components/TemplateList';
import { TestLogicModal } from './components/TestLogicModal';
import { NewTemplateModal } from './components/NewTemplateModal';
import { NewSkeletonModal } from './components/NewSkeletonModal';
import { PublishModal } from './components/PublishModal';
import { TemplateSettingsModal } from './components/TemplateSettingsModal';
import { SiteDetailsModal } from './components/SiteDetailsModal';
import { AuditLogModal } from './components/AuditLogModal';
import { AICloneModal, AICloneOption } from './components/AICloneModal';
import { MOCK_TEMPLATES, TEMPLATE_SKELETONS, getMockSitesForTemplate } from './constants';
import { Template, Block, BlockType, LogicRule, Site, Skeleton, BlockHistoryEntry } from './types';

export function App() {
  const [view, setView] = useState<'list' | 'builder'>('list');
  const [templates, setTemplates] = useState<Template[]>(MOCK_TEMPLATES || []);
  const [template, setTemplate] = useState<Template>(() => {
    return (templates && templates.length > 0) ? templates[0] : null as any;
  });
  const [viewingVersion, setViewingVersion] = useState<string | null>(null);
  const [skeletons, setSkeletons] = useState<Skeleton[]>(TEMPLATE_SKELETONS || []);

  const [expandedBlockIds, setExpandedBlockIds] = useState<Set<string>>(new Set());

  const [sitesByTemplate, setSitesByTemplate] = useState<Record<string, Site[]>>(() => {
    const initialSites: Record<string, Site[]> = {};
    if (MOCK_TEMPLATES) {
      MOCK_TEMPLATES.forEach(t => {
        initialSites[t.id] = getMockSitesForTemplate(t.id, t.version);
      });
    }
    return initialSites;
  });

  const [editingBlock, setEditingBlock] = useState<Block | null>(null);
  const [isModalOpen, setIsModalOpen] = useState(false);

  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [historyBlock, setHistoryBlock] = useState<Block | null>(null);

  const [isLogicModalOpen, setIsLogicModalOpen] = useState(false);
  const [logicBlockId, setLogicBlockId] = useState<string | null>(null);

  const [isTestLogicOpen, setIsTestLogicOpen] = useState(false);
  const [isNewTemplateModalOpen, setIsNewTemplateModalOpen] = useState(false);
  const [isNewSkeletonModalOpen, setIsNewSkeletonModalOpen] = useState(false);
  const [editingSkeleton, setEditingSkeleton] = useState<Skeleton | null>(null);
  const [isPublishModalOpen, setIsPublishModalOpen] = useState(false);
  const [isSettingsModalOpen, setIsSettingsModalOpen] = useState(false);
  const [isSiteDetailsModalOpen, setIsSiteDetailsModalOpen] = useState(false);
  const [isAuditLogOpen, setIsAuditLogOpen] = useState(false);
  const [isAICloneModalOpen, setIsAICloneModalOpen] = useState(false);
  const [blockToCloneId, setBlockToCloneId] = useState<string | null>(null);
  const [showSaveNotification, setShowSaveNotification] = useState(false);

  const [filterType, setFilterType] = useState<BlockType | 'All'>('All');
  const [searchQuery, setSearchQuery] = useState('');
  const [showMismatchOnly, setShowMismatchOnly] = useState(false);
  const [showDerived, setShowDerived] = useState(true);

  const headerTemplate = useMemo(() => {
    if (!template) return null as any;
    if (viewingVersion && viewingVersion !== template.version) {
       const historyItem = template.history?.find(h => h.version === viewingVersion);
       if (historyItem) {
          let computedStatus: Template['status'] = 'Archived';
          if (template.status === 'Draft' && viewingVersion === template.previousVersion) {
              computedStatus = 'Published'; 
          }

          return {
              ...template,
              version: viewingVersion,
              lastUpdated: historyItem.lastUpdated,
              updatedBy: historyItem.updatedBy,
              blocks: historyItem.blocksSnapshot,
              status: computedStatus
          };
       }
    }
    return template;
  }, [template, viewingVersion]);

  const isReadOnlyMode = !!viewingVersion || (template && template.status !== 'Draft');

  const updateTemplateForFirstEdit = (templateToUpdate: Template): Template => {
    if (templateToUpdate.status !== 'Draft') {
        const [major] = templateToUpdate.version.split('.').map(Number);
        const newVersion = `${major}.${1}`;

        const historyEntry = {
            version: templateToUpdate.version,
            lastUpdated: templateToUpdate.lastUpdated,
            updatedBy: templateToUpdate.updatedBy || 'Unknown',
            blocksSnapshot: templateToUpdate.blocks
        };

        return {
            ...templateToUpdate,
            status: 'Draft',
            version: newVersion,
            previousVersion: templateToUpdate.version,
            lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
            updatedBy: 'Liam Alexander',
            history: [historyEntry, ...(templateToUpdate.history || [])]
        };
    }
    return templateToUpdate;
  };

  const handleUnlockTemplate = () => {
    if (template.status !== 'Draft') {
        const newTemplate = updateTemplateForFirstEdit(template);
        setTemplate(newTemplate);
        setTemplates(prev => prev.map(t => t.id === newTemplate.id ? newTemplate : t));
    }
    setViewingVersion(null);
  };

  const handleCreateDraftFromList = (t: Template) => {
      const newTemplate = updateTemplateForFirstEdit(t);
      setTemplate(newTemplate);
      setTemplates(prev => prev.map(old => old.id === newTemplate.id ? newTemplate : old));
      setView('builder');
      setViewingVersion(null);
  };

  const handleSaveDraft = () => {
     const currentDate = new Date().toLocaleDateString('en-GB').replace(/\//g, '.');
     const historyEntry = {
        version: template.version,
        lastUpdated: template.lastUpdated,
        updatedBy: template.updatedBy || 'Liam Alexander',
        blocksSnapshot: template.blocks
     };

     const [major, minor] = template.version.split('.').map(Number);
     const safeMajor = isNaN(major) ? 1 : major;
     const safeMinor = isNaN(minor) ? 0 : minor;
     const newVersion = `${safeMajor}.${safeMinor + 1}`;

     const updatedTemplate: Template = {
         ...template,
         version: newVersion,
         lastUpdated: currentDate,
         history: [historyEntry, ...(template.history || [])]
     };

     setTemplate(updatedTemplate);
     setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));

     setViewingVersion(null);
     setShowSaveNotification(true);
     setTimeout(() => setShowSaveNotification(false), 3000);
  };

  const handleConfirmPublish = (templateId: string) => {
    const publishLogic = (t: Template): Template => {
      if (t.id === templateId && t.status === 'Draft') {
        const currentVersionNumber = parseFloat(t.version);
        const newMajorVersion = isNaN(currentVersionNumber) ? '1.0' : `${Math.floor(currentVersionNumber) + 1}.0`;

        const publishedBlocks = t.blocks.map(block => ({
          ...block,
          editedInDraft: false,
          versionAtSessionStart: block.version,
        }));

        return {
          ...t,
          status: 'Rolling Out',
          version: newMajorVersion,
          previousVersion: t.version,
          blocks: publishedBlocks,
        };
      }
      return t;
    };

    setTemplates(prev => prev.map(publishLogic));
    if (template.id === templateId && template.status === 'Draft') {
      setTemplate(prev => publishLogic(prev));
    }
    setViewingVersion(null);
    setIsPublishModalOpen(false);
  };

  const handleUpdateSites = (templateId: string, siteIdsToUpdate: string[]) => {
     setSitesByTemplate(prev => {
        const sites = prev[templateId] || [];
        const currentTemplate = templates.find(t => t.id === templateId);
        if (!currentTemplate) return prev;

        const updatedSites = sites.map(site => {
           if (siteIdsToUpdate.includes(site.id)) {
             return { ...site, version: currentTemplate.version, lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.') };
           }
           return site;
        });

        const allSitesUpdated = updatedSites.every(s => s.version === currentTemplate.version);

        if (allSitesUpdated && currentTemplate.status === 'Rolling Out') {
             setTimeout(() => {
                 const updateStatus = (t: Template) => t.id === templateId ? { ...t, status: 'Published' as const } : t;
                 setTemplates(prevTemplates => prevTemplates.map(updateStatus));
                 if (template.id === templateId) {
                    setTemplate(prev => ({ ...prev, status: 'Published' }));
                 }
             }, 0);
        }

        return { ...prev, [templateId]: updatedSites };
     });
     setIsPublishModalOpen(false);
  };

  const handleBack = () => {
    setView('list');
    setViewingVersion(null);
    setFilterType('All');
    setSearchQuery('');
    setShowDerived(true);
  };

  const handleSelectTemplate = (t: Template) => {
    setTemplate(t);
    setView('builder');
    setViewingVersion(null);
  };

  const handleSelectVersion = (t: Template, v: string) => {
      setTemplate(t);
      setView('builder');
      setViewingVersion(v);
  };

  const handleCreateTemplate = (name: string, skeletonId: string) => {
    const skeleton = skeletons.find(s => s.id === skeletonId);
    if (!skeleton) return;

    const newTemplate: Template = {
      id: `tmpl_${Date.now()}`,
      name: name,
      skeleton: skeleton.name,
      version: '0.1',
      previousVersion: '0.0',
      lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
      updatedBy: 'Liam Alexander',
      status: 'Draft',
      blocks: skeleton.blocks.map((b, i) => ({
        id: `blk_${Date.now()}_${i}`,
        type: b.type,
        contentName: b.contentName,
        content: b.content,
        version: '0.1',
        lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
        hasEditHistory: false,
        history: [],
        isSyncing: false,
        rules: []
      })),
      history: []
    };

    setTemplates([newTemplate, ...templates]);
    setSitesByTemplate(prev => ({ ...prev, [newTemplate.id]: [] }));
    setIsNewTemplateModalOpen(false);
    handleSelectTemplate(newTemplate);
  };

  const handleCreateSkeleton = (name: string, description: string, blocks: { type: BlockType; name: string; content: string }[]) => {
     const newSkeleton: Skeleton = {
        id: `sk_${Date.now()}`,
        name,
        description,
        status: 'Active',
        blocks: blocks.map(b => ({
           type: b.type,
           contentName: b.name,
           content: b.content,
           version: '1.0',
           lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
           hasEditHistory: false,
           history: [],
           isSyncing: false,
           rules: []
        }))
     };
     setSkeletons([...skeletons, newSkeleton]);
     setIsNewSkeletonModalOpen(false);
  };

  const handleEditSkeleton = (skeleton: Skeleton) => {
     setEditingSkeleton(skeleton);
     setIsNewSkeletonModalOpen(true);
  };

  const handleArchiveSkeleton = (skeletonId: string) => {
     setSkeletons(prev => prev.map(s => s.id === skeletonId ? { ...s, status: 'Archived' } : s));
  };

  const handleSaveSkeleton = (name: string, description: string, blocks: { type: BlockType; name: string; content: string }[]) => {
      if (editingSkeleton) {
        setSkeletons(prev => prev.map(s => s.id === editingSkeleton.id ? {
           ...s,
           name,
           description,
           blocks: blocks.map(b => ({
               type: b.type,
               contentName: b.name,
               content: b.content,
               version: '1.0',
               lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
               hasEditHistory: false,
               history: [],
               isSyncing: false,
               rules: []
           }))
        } : s));
        setEditingSkeleton(null);
        setIsNewSkeletonModalOpen(false);
      } else {
        handleCreateSkeleton(name, description, blocks);
      }
  };

  const handleArchiveTemplate = (templateId: string) => {
     setTemplates(prev => prev.map(t => t.id === templateId ? { ...t, status: 'Archived' } : t));
  };

  const handleToggleExpand = (id: string) => {
    setExpandedBlockIds(prev => {
        const next = new Set(prev);
        if (next.has(id)) next.delete(id);
        else next.add(id);
        return next;
    });
  };

  const handleDeleteBlock = (id: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const updatedBlocks = currentTemplate.blocks.filter(b => b.id !== id);
    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
  };

  const handleDuplicateBlock = (id: string) => {
    setBlockToCloneId(id);
    setIsAICloneModalOpen(true);
  };

  const handleAIClone = (option: AICloneOption) => {
    if (!blockToCloneId) return;

    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const blockToDuplicate = currentTemplate.blocks.find(b => b.id === blockToCloneId);
    if (blockToDuplicate) {
      let transformedContent = blockToDuplicate.content || '';
      let suffix = '';

      switch (option) {
        case 'simplify':
          transformedContent = transformedContent + "\n\n[AI: Simplified Content]";
          suffix = ' (Simplified)';
          break;
        case 'past_tense':
          transformedContent = transformedContent.replace(/will be/g, "was").replace(/is/g, "was") + "\n\n[AI: Converted to Past Tense]";
          suffix = ' (Past Tense)';
          break;
        case 'future_tense':
          transformedContent = transformedContent.replace(/was/g, "will be").replace(/is/g, "will be") + "\n\n[AI: Converted to Future Tense]";
          suffix = ' (Future Tense)';
          break;
        case 'formal':
          transformedContent = "The aforementioned " + transformedContent.toLowerCase() + "\n\n[AI: Formal Tone Applied]";
          suffix = ' (Formal)';
          break;
        case 'standard':
        default:
          break;
      }

      const newBlock: Block = {
        ...blockToDuplicate,
        id: `blk_${Date.now()}`,
        contentName: `Copy of ${blockToDuplicate.contentName}${suffix}`,
        content: transformedContent,
        version: blockToDuplicate.version,
        isCloned: true,
        clonedFrom: blockToDuplicate.id,
        derivedFromVersion: blockToDuplicate.version,
        subLabel: `Derived from ${blockToDuplicate.contentName} ${blockToDuplicate.version}${option !== 'standard' ? ` via AI (${option})` : ''}`,
        rules: [],
        editedInDraft: true,
        isDraftCopy: true,
        associatedDomainIds: blockToDuplicate.associatedDomainIds ? [...blockToDuplicate.associatedDomainIds] : [],
        history: [{
            version: blockToDuplicate.version,
            templateVersion: currentTemplate.version,
            updatedAt: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
            editedBy: 'Liam Alexander',
            changeDescription: `Created via ${option === 'standard' ? 'duplication' : 'AI transformation'}`,
            contentSnapshot: transformedContent
        }]
      };

      const index = currentTemplate.blocks.findIndex(b => b.id === blockToCloneId);
      const newBlocks = [...currentTemplate.blocks];
      newBlocks.splice(index + 1, 0, newBlock);

      const updatedTemplate = { ...currentTemplate, blocks: newBlocks };
      setTemplate(updatedTemplate);
      setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
    }

    setIsAICloneModalOpen(false);
    setBlockToCloneId(null);
  };

  const handleUpdateNote = (blockId: string, note: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
       currentTemplate = updateTemplateForFirstEdit(template);
       setTemplate(currentTemplate);
       setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const updatedBlocks = currentTemplate.blocks.map(b => 
      b.id === blockId ? { ...b, notes: note } : b
    );

    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
  };

  const handleReorderBlocks = (draggedBlockId: string, targetBlockId: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const blocks = [...currentTemplate.blocks];
    const draggedBlock = blocks.find(b => b.id === draggedBlockId);
    if (!draggedBlock) return;

    const blocksWithoutDragged = blocks.filter(b => b.id !== draggedBlockId);
    const targetIndex = blocksWithoutDragged.findIndex(b => b.id === targetBlockId);
    if (targetIndex === -1) return;

    blocksWithoutDragged.splice(targetIndex, 0, draggedBlock);

    const updatedTemplate = { ...currentTemplate, blocks: blocksWithoutDragged };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
  };

  const handleEditContent = (block: Block) => {
    setEditingBlock(block);
    setIsModalOpen(true);
  };

  const handleSaveBlock = (blockId: string, name: string, type: BlockType, content: string, rules: LogicRule[], associatedDomainIds?: string[]) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const [tmplMajor] = currentTemplate.version.split('.').map(Number);
    const currentBlock = currentTemplate.blocks.find(b => b.id === blockId);
    let newVersion = '1.0';
    if (currentBlock) {
        const [blkMajor, blkMinor] = currentBlock.version.split('.').map(Number);
        const safeBlkMajor = isNaN(blkMajor) ? 1 : blkMajor;
        const safeBlkMinor = isNaN(blkMinor) ? 0 : blkMinor;
        const safeTmplMajor = isNaN(tmplMajor) ? 1 : tmplMajor;

        if (safeBlkMajor === safeTmplMajor) {
            newVersion = `${safeBlkMajor}.${safeBlkMinor + 1}`;
        } else {
            newVersion = `${safeTmplMajor}.1`;
        }
    }

    const currentDate = new Date().toLocaleDateString('en-GB').replace(/\//g, '.');

    const updatedBlocks = currentTemplate.blocks.map(b => {
      if (b.id === blockId) {
        const historyEntry: BlockHistoryEntry = {
          version: b.version,
          templateVersion: currentTemplate.version,
          updatedAt: b.lastUpdated,
          editedBy: 'Liam Alexander',
          changeDescription: b.content !== content ? 'Content updated' : 'Properties updated',
          contentSnapshot: b.content || ''
        };

        return {
          ...b,
          contentName: name,
          type,
          content,
          rules,
          associatedDomainIds,
          version: newVersion,
          lastUpdated: currentDate,
          history: [historyEntry, ...b.history],
          editedInDraft: true,
          hasEditHistory: true
        };
      }
      return b;
    });

    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
    setIsModalOpen(false);
    setEditingBlock(null);
  };

  const handleShowHistory = (block: Block) => {
    setHistoryBlock(block);
    setIsHistoryOpen(true);
  };

  const handleAddLogic = (blockId: string) => {
    setLogicBlockId(blockId);
    setIsLogicModalOpen(true);
  };

  const handleSaveLogicRule = (ruleData: Omit<LogicRule, 'id'>) => {
    if (!logicBlockId) return;

    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const newRule: LogicRule = {
        ...ruleData,
        id: `rule_${Date.now()}`
    };

    const updatedBlocks = currentTemplate.blocks.map(b => {
        if (b.id === logicBlockId) {
             const [major, minor] = b.version.split('.').map(Number);
             const safeMajor = isNaN(major) ? 1 : major;
             const safeMinor = isNaN(minor) ? 0 : minor;
             const newVersion = `${safeMajor}.${safeMinor + 1}`;

             const historyEntry: BlockHistoryEntry = {
                 version: b.version,
                 templateVersion: currentTemplate.version,
                 updatedAt: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 editedBy: 'Liam Alexander',
                 changeDescription: 'Logic rule added',
                 contentSnapshot: b.content || ''
             };

             return {
                 ...b,
                 rules: [...b.rules, newRule],
                 version: newVersion,
                 lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 history: [historyEntry, ...b.history],
                 editedInDraft: true,
                 hasEditHistory: true
             };
        }
        return b;
    });

    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
    setIsLogicModalOpen(false);
    setLogicBlockId(null);
  };

  const handleDeleteLogic = (blockId: string, ruleId: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const updatedBlocks = currentTemplate.blocks.map(b => {
        if (b.id === blockId) {
             const [major, minor] = b.version.split('.').map(Number);
             const safeMajor = isNaN(major) ? 1 : major;
             const safeMinor = isNaN(minor) ? 0 : minor;
             const newVersion = `${safeMajor}.${safeMinor + 1}`;

             const historyEntry: BlockHistoryEntry = {
                 version: b.version,
                 templateVersion: currentTemplate.version,
                 updatedAt: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 editedBy: 'Liam Alexander',
                 changeDescription: 'Logic rule removed',
                 contentSnapshot: b.content || ''
             };

             return {
                 ...b,
                 rules: b.rules.filter(r => r.id !== ruleId),
                 version: newVersion,
                 lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 history: [historyEntry, ...b.history],
                 editedInDraft: true,
                 hasEditHistory: true
             };
        }
        return b;
    });

    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
  };

  const handleToggleDisable = (blockId: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const updatedBlocks = currentTemplate.blocks.map(b => {
        if (b.id === blockId) {
             const [major, minor] = b.version.split('.').map(Number);
             const safeMajor = isNaN(major) ? 1 : major;
             const safeMinor = isNaN(minor) ? 0 : minor;
             const newVersion = `${safeMajor}.${safeMinor + 1}`;
             const newDisabledState = !b.isDisabled;

             const historyEntry: BlockHistoryEntry = {
                 version: b.version,
                 templateVersion: currentTemplate.version,
                 updatedAt: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 editedBy: 'Liam Alexander',
                 changeDescription: newDisabledState ? 'Block disabled' : 'Block enabled',
                 contentSnapshot: b.content || ''
             };

             return {
                 ...b,
                 isDisabled: newDisabledState,
                 version: newVersion,
                 lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
                 history: [historyEntry, ...b.history],
                 editedInDraft: true,
                 hasEditHistory: true
             };
        }
        return b;
    });

    const updatedTemplate = { ...currentTemplate, blocks: updatedBlocks };
    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
  };

  const handleAddNewBlock = (afterBlockId?: string) => {
    let currentTemplate = template;
    if (template.status !== 'Draft') {
        currentTemplate = updateTemplateForFirstEdit(template);
        setTemplate(currentTemplate);
        setTemplates(prev => prev.map(t => t.id === currentTemplate.id ? currentTemplate : t));
    }

    const newBlock: Block = {
        id: `blk_${Date.now()}`,
        type: 'Universal',
        contentName: 'Add content',
        content: '',
        version: '0.1',
        lastUpdated: new Date().toLocaleDateString('en-GB').replace(/\//g, '.'),
        hasEditHistory: false,
        history: [],
        isSyncing: false,
        rules: []
    };

    let newBlocks = [...currentTemplate.blocks];
    if (afterBlockId) {
        const index = newBlocks.findIndex(b => b.id === afterBlockId);
        if (index !== -1) {
            newBlocks.splice(index + 1, 0, newBlock);
        } else {
            newBlocks.push(newBlock);
        }
    } else {
        newBlocks.push(newBlock);
    }

    const updatedTemplate = {
        ...currentTemplate,
        blocks: newBlocks
    };

    setTemplate(updatedTemplate);
    setTemplates(prev => prev.map(t => t.id === updatedTemplate.id ? updatedTemplate : t));
    setEditingBlock(newBlock);
    setIsModalOpen(true);
  };

  const filteredBlocks = useMemo(() => {
    if (!headerTemplate || !headerTemplate.blocks) return [];
    let blocks = headerTemplate.blocks;

    if (filterType !== 'All') {
      blocks = blocks.filter(b => b.type === filterType);
    }

    if (searchQuery) {
      const q = searchQuery.toLowerCase();
      blocks = blocks.filter(b => 
        b.contentName.toLowerCase().includes(q) || 
        (b.content && b.content.toLowerCase().includes(q))
      );
    }

    if (showMismatchOnly) {
       blocks = blocks.filter(b => {
           if (!b.isCloned || !b.clonedFrom) return false;
           const parent = headerTemplate.blocks.find(p => p.id === b.clonedFrom);
           return parent && parent.version !== b.derivedFromVersion;
       });
    }

    if (!showDerived && !showMismatchOnly && !searchQuery) {
        blocks = blocks.filter(b => !b.isCloned);
    }

    return blocks;
  }, [headerTemplate, filterType, searchQuery, showMismatchOnly, showDerived]);

  const blocksToRender = useMemo(() => {
      return filteredBlocks.map(b => ({
          ...b,
          isExpanded: expandedBlockIds.has(b.id)
      }));
  }, [filteredBlocks, expandedBlockIds]);

  const areAllExpanded = useMemo(() => {
    if (filteredBlocks.length === 0) return false;
    return filteredBlocks.every(b => expandedBlockIds.has(b.id));
  }, [filteredBlocks, expandedBlockIds]);

  const handleToggleExpandAll = () => {
    if (areAllExpanded) {
       setExpandedBlockIds(prev => {
          const next = new Set(prev);
          filteredBlocks.forEach(b => next.delete(b.id));
          return next;
       });
    } else {
       setExpandedBlockIds(prev => {
          const next = new Set(prev);
          filteredBlocks.forEach(b => next.add(b.id));
          return next;
       });
    }
  };

  const latestPublishedVersion = useMemo(() => {
     if (!template) return null;
     if (template.status === 'Published' || template.status === 'Rolling Out' || template.status === 'Archived') {
         return template.version;
     }

     const candidates = new Set<string>();
     if (template.previousVersion) candidates.add(template.previousVersion);
     if (template.history) {
         template.history.forEach(h => candidates.add(h.version));
     }

     const publishedVersions = Array.from(candidates)
         .filter(v => v.endsWith('.0'))
         .sort((a, b) => parseFloat(b) - parseFloat(a));

     return publishedVersions.length > 0 ? publishedVersions[0] : null;
  }, [template]);

  const canReorder = !isReadOnlyMode && filterType === 'All' && !searchQuery && !showMismatchOnly && showDerived;

  if (!template) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50">
        <div className="text-center p-8">
           <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
           <p className="text-gray-500">Loading templates...</p>
        </div>
      </div>
    );
  }

  if (view === 'list') {
    return (
      <div className="min-h-screen bg-gray-50/50 p-8 font-sans">
        <div className="max-w-7xl mx-auto">
          <TemplateList 
            templates={templates}
            skeletons={skeletons}
            sitesByTemplate={sitesByTemplate}
            onSelectTemplate={handleSelectTemplate}
            onSelectVersion={handleSelectVersion}
            onCreateTemplate={() => setIsNewTemplateModalOpen(true)}
            onCreateSkeleton={() => setIsNewSkeletonModalOpen(true)}
            onEditSkeleton={handleEditSkeleton}
            onArchiveSkeleton={handleArchiveSkeleton}
            onTestLogic={(t) => {
              setTemplate(t);
              setIsTestLogicOpen(true);
            }}
            onArchive={handleArchiveTemplate}
            onUpdateSite={(tId, sId) => {
                 setSitesByTemplate(prev => {
                     const list = prev[tId] || [];
                     const tmpl = templates.find(t => t.id === tId);
                     return {
                         ...prev,
                         [tId]: list.map(s => s.id === sId && tmpl ? { ...s, version: tmpl.version } : s)
                     };
                 });
            }}
            onOpenSiteDetails={(t) => {
               if(t) setTemplate(t);
               setIsSiteDetailsModalOpen(true);
            }}
            onCreateDraft={handleCreateDraftFromList}
          />
        </div>

        {isNewTemplateModalOpen && (
          <NewTemplateModal 
            isOpen={isNewTemplateModalOpen} 
            onClose={() => setIsNewTemplateModalOpen(false)}
            onCreate={handleCreateTemplate}
            skeletons={skeletons}
          />
        )}

        {isNewSkeletonModalOpen && (
          <NewSkeletonModal 
            isOpen={isNewSkeletonModalOpen}
            onClose={() => { setIsNewSkeletonModalOpen(false); setEditingSkeleton(null); }}
            onSave={handleSaveSkeleton}
            initialSkeleton={editingSkeleton}
          />
        )}

        {isTestLogicOpen && (
           <TestLogicModal 
             isOpen={isTestLogicOpen}
             onClose={() => setIsTestLogicOpen(false)}
             template={template}
           />
        )}

        {isSiteDetailsModalOpen && (
           <SiteDetailsModal
             isOpen={isSiteDetailsModalOpen}
             onClose={() => setIsSiteDetailsModalOpen(false)}
             template={template}
             allTemplates={templates}
             sites={sitesByTemplate[template.id] || []}
             onUpdateSites={handleUpdateSites}
             onSelectTemplate={setTemplate}
           />
        )}
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50/50 font-sans pb-20">

      <div className="bg-white border-b border-gray-200 sticky top-0 z-30">
         <div className="max-w-7xl mx-auto px-6 py-4">
            <Header 
              template={headerTemplate}
              selectedVersion={viewingVersion || template.version}
              isReadOnly={isReadOnlyMode}
              realStatus={template.status}
              latestPublishedVersion={latestPublishedVersion}
              onBack={handleBack}
              onTestLogic={() => setIsTestLogicOpen(true)}
              onPublish={() => setIsPublishModalOpen(true)}
              onOpenSettings={() => setIsSettingsModalOpen(true)}
              onUnlock={handleUnlockTemplate}
              onSaveDraft={handleSaveDraft}
              onOpenAuditLog={() => setIsAuditLogOpen(true)}
            />
         </div>
      </div>

      <div className="max-w-7xl mx-auto px-6 py-6">

        <FilterBar 
          selectedType={filterType}
          onTypeChange={setFilterType}
          searchQuery={searchQuery}
          onSearchChange={setSearchQuery}
          showMismatchOnly={showMismatchOnly}
          onToggleMismatch={() => setShowMismatchOnly(!showMismatchOnly)}
          showDerived={showDerived}
          onToggleDerived={() => setShowDerived(!showDerived)}
          areAllExpanded={areAllExpanded}
          onToggleExpandAll={handleToggleExpandAll}
        />

        <BlockList 
          blocks={blocksToRender} 
          allBlocks={headerTemplate.blocks}
          isReadOnly={isReadOnlyMode}
          onToggleExpand={handleToggleExpand}
          onDeleteBlock={handleDeleteBlock}
          onDuplicateBlock={handleDuplicateBlock}
          onEditContent={handleEditContent}
          onShowHistory={handleShowHistory}
          onAddLogic={handleAddLogic}
          onDeleteLogic={handleDeleteLogic}
          onRevertBlock={() => {}} 
          onToggleDisable={handleToggleDisable}
          onReorderBlocks={handleReorderBlocks}
          onUpdateNote={handleUpdateNote}
          onAddBlock={handleAddNewBlock}
          canReorder={canReorder}
        />

      </div>

      {isModalOpen && (
        <BlockModal 
          isOpen={isModalOpen}
          onClose={() => { setIsModalOpen(false); setEditingBlock(null); }}
          onSave={handleSaveBlock}
          initialBlock={editingBlock}
          existingBlocks={headerTemplate.blocks}
          parentBlock={editingBlock?.clonedFrom ? headerTemplate.blocks.find(b => b.id === editingBlock.clonedFrom) : undefined}
        />
      )}

      {isHistoryOpen && (
        <HistoryModal 
          isOpen={isHistoryOpen}
          onClose={() => setIsHistoryOpen(false)}
          block={historyBlock}
          currentTemplateVersion={headerTemplate.version}
        />
      )}

      {isLogicModalOpen && (
        <LogicModal 
          isOpen={isLogicModalOpen}
          onClose={() => setIsLogicModalOpen(false)}
          onSave={handleSaveLogicRule}
        />
      )}

      {isTestLogicOpen && (
         <TestLogicModal 
           isOpen={isTestLogicOpen}
           onClose={() => setIsTestLogicOpen(false)}
           template={headerTemplate}
         />
      )}

      {isPublishModalOpen && (
         <PublishModal 
           isOpen={isPublishModalOpen}
           onClose={() => setIsPublishModalOpen(false)}
           templateId={template.id}
           templateName={template.name}
           currentVersion={template.version}
           status={template.status}
           sites={sitesByTemplate[template.id] || []}
           onConfirm={handleConfirmPublish}
           onConfirmUpdates={handleUpdateSites}
         />
      )}

      {isSettingsModalOpen && (
         <TemplateSettingsModal
            isOpen={isSettingsModalOpen}
            onClose={() => setIsSettingsModalOpen(false)}
            template={template}
         />
      )}

      {isAuditLogOpen && (
        <AuditLogModal 
          isOpen={isAuditLogOpen}
          onClose={() => setIsAuditLogOpen(false)}
          template={headerTemplate}
        />
      )}

      {isAICloneModalOpen && blockToCloneId && (
        <AICloneModal 
          isOpen={isAICloneModalOpen}
          onClose={() => { setIsAICloneModalOpen(false); setBlockToCloneId(null); }}
          onConfirm={handleAIClone}
          blockName={headerTemplate.blocks.find(b => b.id === blockToCloneId)?.contentName || 'Unknown Block'}
        />
      )}

      {showSaveNotification && (
        <div className="fixed bottom-6 right-6 bg-gray-900 text-white px-4 py-3 rounded-lg shadow-lg flex items-center gap-3 animate-in fade-in slide-in-from-bottom-4 z-50">
          <div className="bg-emerald-500 rounded-full p-1">
            <svg className="w-3 h-3 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <div>
            <h4 className="font-medium text-sm">Draft Saved</h4>
            <p className="text-xs text-gray-400">Version {template.version} created</p>
          </div>
        </div>
      )}

    </div>
  );
}

import React, { useState, useMemo } from 'react';
import { 
  Plus, 
  Search,
  ChevronLeft,
  ChevronRight,
  Building2,
  Clock,
  User,
  Eye,
  PenLine
} from 'lucide-react';
import { Template, Site, Skeleton } from '../types';

interface TemplateListProps {
  templates: Template[];
  skeletons: Skeleton[];
  sitesByTemplate: Record<string, Site[]>;
  onSelectTemplate: (template: Template) => void;
  onSelectVersion: (template: Template, version: string) => void;
  onCreateTemplate: () => void;
  onCreateSkeleton: () => void;
  onEditSkeleton: (skeleton: Skeleton) => void;
  onArchiveSkeleton: (skeletonId: string) => void;
  onTestLogic: (template: Template) => void;
  onArchive: (templateId: string) => void;
  onUpdateSite: (templateId: string, siteId: string) => void;
  onOpenSiteDetails: (template?: Template) => void;
  onCreateDraft?: (template: Template) => void;
}

const getStatusStyles = (status: string) => {
  switch (status) {
    case 'Published':
      return 'text-emerald-700 bg-emerald-50 border-emerald-200 font-bold';
    case 'Rolling Out':
      return 'text-purple-700 bg-purple-50 border-purple-200 font-bold';
    case 'Draft':
      return 'text-amber-700 bg-amber-50 border-amber-200 font-bold';
    case 'Archived':
      return 'text-gray-700 bg-gray-50 border-gray-200';
    case 'Snapshot':
      return 'text-slate-600 bg-slate-100 border-slate-200';
    default:
      return 'text-gray-700 bg-gray-50 border-gray-200';
  }
};

interface VersionRowProps {
  version: string;
  status: string;
  lastUpdated: string;
  updatedBy: string;
  isCurrent: boolean;
  onView: () => void;
}

const VersionRow: React.FC<VersionRowProps> = ({ 
  version, 
  status, 
  lastUpdated, 
  updatedBy, 
  isCurrent, 
  onView
}) => {
  const isDraft = status === 'Draft';

  return (
    <tr className={`group transition-colors hover:bg-gray-50/50 ${isCurrent ? 'bg-indigo-50/10' : ''}`}>
      <td className="px-6 py-4 whitespace-nowrap">
        <button 
          onClick={(e) => { e.stopPropagation(); onView(); }}
          className="flex items-center gap-2 group/ver outline-none text-left"
        >
           <span className={`font-mono text-sm transition-all ${
             isCurrent 
               ? 'font-bold text-indigo-700' 
               : 'font-semibold text-gray-900 group-hover/ver:text-indigo-600 group-hover/ver:underline'
           }`}>
             v{version}
           </span>
        </button>
      </td>

      <td className="px-6 py-4 whitespace-nowrap">
        <span className={`inline-flex items-center px-2.5 py-1 rounded-full text-[10px] uppercase tracking-wider border ${getStatusStyles(status)}`}>
          {status}
        </span>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
          <div className="flex items-center gap-1.5">
             <Clock className="w-3.5 h-3.5 text-gray-400" />
             {lastUpdated}
          </div>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
          <div className="flex items-center gap-1.5">
             <User className="w-3.5 h-3.5 text-gray-400" />
             {updatedBy}
          </div>
      </td>

      <td className="px-6 py-4 whitespace-nowrap text-sm text-right">
        <div className="flex items-center justify-end gap-2">
            <button
            onClick={(e) => { e.stopPropagation(); onView(); }}
            className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg border text-xs font-medium transition-colors shadow-sm ${
                isDraft
                ? 'border-indigo-200 bg-indigo-50 text-indigo-700 hover:bg-indigo-100'
                : 'border-gray-200 bg-white text-gray-700 hover:bg-gray-50 hover:text-indigo-600'
            }`}
            >
            {isDraft ? <PenLine className="w-3.5 h-3.5" /> : <Eye className="w-3.5 h-3.5" />}
            {isDraft ? 'Edit' : 'View'}
            </button>
        </div>
      </td>
    </tr>
  );
};

export const TemplateList: React.FC<TemplateListProps> = ({ templates, sitesByTemplate, onSelectVersion, onCreateTemplate, onOpenSiteDetails, onTestLogic, onCreateDraft }) => {
  const [searchQuery, setSearchQuery] = useState('');
  const [currentPage, setCurrentPage] = useState(1);
  const itemsPerPage = 10;

  const activeTemplate = templates.length > 0 ? templates[0] : null;

  const versions = useMemo(() => {
      if (!activeTemplate) return [];

      const list = [
          {
              version: activeTemplate.version,
              status: activeTemplate.status,
              lastUpdated: activeTemplate.lastUpdated,
              updatedBy: activeTemplate.updatedBy || 'Unknown',
              isCurrent: true
          }
      ];

      if (activeTemplate.history && activeTemplate.history.length > 0) {
          activeTemplate.history.forEach(h => {
              const verNum = parseFloat(h.version);

              let inferredStatus: string;
              if (activeTemplate.status === 'Draft' && h.version === activeTemplate.previousVersion) {
                  inferredStatus = 'Rolling Out';
              } else {
                  const isMajor = h.version.endsWith('.0');
                  inferredStatus = isMajor ? 'Published' : 'Archived';

                  if (!isMajor || (activeTemplate.previousVersion && parseFloat(h.version) < parseFloat(activeTemplate.previousVersion))) {
                      inferredStatus = 'Archived';
                  }
              }

              list.push({
                  version: h.version,
                  status: inferredStatus,
                  lastUpdated: h.lastUpdated,
                  updatedBy: h.updatedBy,
                  isCurrent: false
              });
          });
      }

      if (searchQuery) {
          return list.filter(v => v.version.includes(searchQuery) || v.updatedBy.toLowerCase().includes(searchQuery.toLowerCase()));
      }

      return list.sort((a, b) => parseFloat(b.version) - parseFloat(a.version));
  }, [activeTemplate, searchQuery]);

  const totalPages = Math.ceil(versions.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const endIndex = startIndex + itemsPerPage;
  const currentVersions = versions.slice(startIndex, endIndex);

  const handlePageChange = (page: number) => {
    if (page >= 1 && page <= totalPages) {
      setCurrentPage(page);
    }
  };

  const handleViewVersion = (versionItem: any) => {
      if (versionItem.isCurrent && activeTemplate?.status === 'Draft') {
          onSelectVersion(activeTemplate!, versionItem.version);
      } else {
          const snapshotTemplate: Template = {
              ...activeTemplate!,
              version: versionItem.version,
              status: versionItem.status as Template['status'],
              lastUpdated: versionItem.lastUpdated,
              updatedBy: versionItem.updatedBy,
              blocks: activeTemplate!.history?.find(h => h.version === versionItem.version)?.blocksSnapshot || activeTemplate!.blocks
          };
          onTestLogic(snapshotTemplate);
      }
  };

  if (!activeTemplate) return null;

  return (
    <div>
      <div className="flex flex-col md:flex-row justify-between items-start md:items-end gap-6 mb-8">
        <div>
          <h1 className="text-4xl font-serif font-bold text-gray-900 tracking-tight">{activeTemplate.name}</h1>
          <div className="flex items-center gap-3 mt-2">
            <span className="font-mono text-[10px] text-gray-400 bg-gray-100 px-2 py-0.5 rounded border border-gray-200 uppercase tracking-wider">{activeTemplate.id}</span>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => onOpenSiteDetails(activeTemplate)}
            className="px-5 py-2.5 rounded-lg border border-gray-200 bg-white text-gray-700 text-sm font-medium hover:bg-gray-50 hover:border-gray-300 transition-all flex items-center gap-2 shadow-sm"
          >
            <Building2 className="w-4 h-4 text-gray-500" /> Manage Sites
          </button>

          <button 
            onClick={() => onCreateDraft?.(activeTemplate)}
            className="px-5 py-2.5 rounded-lg bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-bold transition-all flex items-center gap-2 shadow-md hover:shadow-lg"
          >
            <Plus className="w-4 h-4" /> Create Draft
          </button>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 mb-6">
        <div className="flex flex-col gap-1 w-full sm:w-[320px] sm:ml-auto">
          <div className="relative">
            <input 
              type="text" 
              placeholder="Search versions..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-9 pr-4 py-2 rounded-md border border-gray-200 bg-white text-sm focus:outline-none focus:ring-1 focus:ring-indigo-500 transition-all placeholder:text-gray-400 shadow-sm"
            />
            <Search className="w-4 h-4 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
          </div>
        </div>
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-gray-200 overflow-hidden flex flex-col">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-gray-100">
            <thead className="bg-gray-50/50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Version</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Status</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Last Updated</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-bold text-gray-500 uppercase tracking-wider">Updated By</th>
                <th scope="col" className="relative px-6 py-3 text-right text-xs font-bold text-gray-500 uppercase tracking-wider">Action</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-100">
              {currentVersions.map((v) => (
                <VersionRow 
                  key={v.version}
                  version={v.version}
                  status={v.status}
                  lastUpdated={v.lastUpdated}
                  updatedBy={v.updatedBy}
                  isCurrent={v.isCurrent}
                  onView={() => handleViewVersion(v)}
                />
              ))}
            </tbody>
          </table>
        </div>

        {versions.length > itemsPerPage && (
          <div className="px-6 py-4 bg-gray-50/50 border-t border-gray-200 flex items-center justify-between text-sm text-gray-600">
            <div>
              Showing <span className="font-semibold">{startIndex + 1}</span> to <span className="font-semibold">{Math.min(endIndex, versions.length)}</span> of <span className="font-semibold">{versions.length}</span>
            </div>
            <div className="flex items-center gap-2">
                <button onClick={() => handlePageChange(currentPage - 1)} disabled={currentPage === 1} className="p-1.5 rounded-md border border-gray-300 bg-white hover:bg-gray-50 disabled:opacity-50">
                  <ChevronLeft className="w-4 h-4" />
                </button>
                <span className="text-sm font-medium text-gray-700">Page {currentPage} of {totalPages}</span>
                <button onClick={() => handlePageChange(currentPage + 1)} disabled={currentPage === totalPages} className="p-1.5 rounded-md border border-gray-300 bg-white hover:bg-gray-50 disabled:opacity-50">
                  <ChevronRight className="w-4 h-4" />
                </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

