  latestPublishedVersion?: string | null;
  onBack: () => void;
  onTestLogic: () => void;
  onPublish: () => void;
  onOpenSettings: () => void;
  onUnlock: () => void;
  onSaveDraft: () => void;
  onOpenAuditLog: () => void;
}

const getStatusStyles = (status: Template['status']) => {
  switch (status) {
    case 'Published':
      return 'bg-emerald-100 text-emerald-800';
    case 'Rolling Out':
      return 'bg-purple-100 text-purple-800';
    case 'Draft':
      return 'bg-amber-100 text-amber-800 font-medium';
    case 'Archived':
      return 'bg-gray-100 text-gray-800';
    default:
      return 'bg-gray-100 text-gray-800';
  }
};

